// FirstOrCreate returns the first primary-ordered matching model or creates one through its normal lifecycle. The draft is prepared only when no model matches; the stored creation must satisfy the query. Internal lookup skips Retrieved. Concurrent absence relies on database unique constraints and reports ordinary conflicts without hidden retries.
func (q FactorQuery) FirstOrCreate(ctx context.Context, writer database.Transactor, create FactorDraft) (Factor, error) {
	return q.Query.FirstOrInsert(ctx, writer, create)
}

// UpdateOrCreate runs a concrete draft callback for the first primary-ordered matching model or creates from the separate creation draft. Only the chosen branch prepares its draft; ordinary lifecycle and transaction ownership remain in force. Read ordering, pagination and eager-loading options are rejected.
func (q FactorQuery) UpdateOrCreate(ctx context.Context, writer database.Transactor, create FactorDraft, draft func(context.Context, *database.Tx, Factor) (FactorDraft, error)) (Factor, error) {
	var callback func(context.Context, *database.Tx, Factor) (foundryquery.Mutation[Factor], error)
	if draft != nil {
		callback = func(ctx context.Context, tx *database.Tx, current Factor) (foundryquery.Mutation[Factor], error) {
			d, err := draft(ctx, tx, current)
			if err != nil {
				return foundryquery.Mutation[Factor]{}, err
			}
			return d.foundryMutation(false)
		}
	}
	return q.Query.PatchOrInsert(ctx, writer, create, callback)
}

