// FoundryCreateMutation supplies the typed draft adapter for framework integrations. Defaults fill omitted fields before UUID preparation; no mutators or database calls run here.
func (d FactorDraft) FoundryCreateMutation(defaults foundryquery.Mutation[Factor]) (foundryquery.Mutation[Factor], error) {
	values, err := foundryquery.ReadCreateDefaults((Factor{}).FoundryQuery(), defaults)
	if err != nil {
		return foundryquery.Mutation[Factor]{}, err
	}
	if !d.fieldKey.IsSet() {
		v, err := foundryquery.MutationValue[Factor, string](values, "foundry_mfa_factors", "key")
		if err != nil {
			return foundryquery.Mutation[Factor]{}, err
		}
		d.fieldKey = v
	}
	if !d.fieldScope.IsSet() {
		v, err := foundryquery.MutationValue[Factor, string](values, "foundry_mfa_factors", "scope")
		if err != nil {
			return foundryquery.Mutation[Factor]{}, err
		}
		d.fieldScope = v
	}
	if !d.fieldIdentity.IsSet() {
		v, err := foundryquery.MutationValue[Factor, foundryvalue.JSON[model.Identity]](values, "foundry_mfa_factors", "identity")
		if err != nil {
			return foundryquery.Mutation[Factor]{}, err
		}
		d.fieldIdentity = v
	}
	if !d.fieldGeneration.IsSet() {
		v, err := foundryquery.MutationValue[Factor, model.ID[Factor]](values, "foundry_mfa_factors", "generation")
		if err != nil {
			return foundryquery.Mutation[Factor]{}, err
		}
		d.fieldGeneration = v
	}
	if !d.fieldCiphertext.IsSet() {
		v, err := foundryquery.MutationValue[Factor, string](values, "foundry_mfa_factors", "ciphertext")
		if err != nil {
			return foundryquery.Mutation[Factor]{}, err
		}
		d.fieldCiphertext = v
	}
	if !d.fieldCreatedAt.IsSet() {
		v, err := foundryquery.MutationValue[Factor, temporal.DateTime](values, "foundry_mfa_factors", "created_at")
		if err != nil {
			return foundryquery.Mutation[Factor]{}, err
		}
		d.fieldCreatedAt = v
	}
	if !d.fieldPendingUntil.IsSet() {
		v, err := foundryquery.MutationValue[Factor, foundryvalue.Nullable[temporal.DateTime]](values, "foundry_mfa_factors", "pending_until")
		if err != nil {
			return foundryquery.Mutation[Factor]{}, err
		}
		d.fieldPendingUntil = v
	}
	if !d.fieldConfirmedAt.IsSet() {
		v, err := foundryquery.MutationValue[Factor, foundryvalue.Nullable[temporal.DateTime]](values, "foundry_mfa_factors", "confirmed_at")
		if err != nil {
			return foundryquery.Mutation[Factor]{}, err
		}
		d.fieldConfirmedAt = v
	}
	if !d.fieldLastStep.IsSet() {
		v, err := foundryquery.MutationValue[Factor, foundryvalue.Nullable[int64]](values, "foundry_mfa_factors", "last_step")
		if err != nil {
			return foundryquery.Mutation[Factor]{}, err
		}
		d.fieldLastStep = v
	}
	if !d.fieldRecoveryHashes.IsSet() {
		v, err := foundryquery.MutationValue[Factor, foundryvalue.JSON[[]string]](values, "foundry_mfa_factors", "recovery_hashes")
		if err != nil {
			return foundryquery.Mutation[Factor]{}, err
		}
		d.fieldRecoveryHashes = v
	}
	return d.foundryMutation(true)
}
func (d FactorDraft) foundryMutation(create bool) (foundryquery.Mutation[Factor], error) {
	var assignments []foundryquery.Assignment[Factor]
	if v, set := d.fieldKey.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Factor]("foundry_mfa_factors", "key", codec.String[string](), v))
	}
	if v, set := d.fieldScope.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Factor]("foundry_mfa_factors", "scope", codec.String[string](), v))
	}
	if v, set := d.fieldIdentity.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Factor]("foundry_mfa_factors", "identity", codec.JSON[model.Identity](), v))
	}
	if v, set := d.fieldGeneration.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Factor]("foundry_mfa_factors", "generation", codec.ID[Factor](), v))
	}
	if v, set := d.fieldCiphertext.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Factor]("foundry_mfa_factors", "ciphertext", codec.String[string](), v))
	}
	if v, set := d.fieldCreatedAt.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Factor]("foundry_mfa_factors", "created_at", codec.DateTime(), v))
	}
	if v, set := d.fieldPendingUntil.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Factor]("foundry_mfa_factors", "pending_until", codec.Nullable(codec.DateTime()), v))
	}
	if v, set := d.fieldConfirmedAt.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Factor]("foundry_mfa_factors", "confirmed_at", codec.Nullable(codec.DateTime()), v))
	}
	if v, set := d.fieldLastStep.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Factor]("foundry_mfa_factors", "last_step", codec.Nullable(codec.Signed[int64]()), v))
	}
	if v, set := d.fieldRecoveryHashes.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Factor]("foundry_mfa_factors", "recovery_hashes", codec.JSON[[]string](), v))
	}
	return foundryquery.Change(assignments...), nil
}

