func foundryFactorSnapshot(snapshot foundryvalue.Optional[Factor]) foundryvalue.Optional[Factor] {
	item, present := snapshot.Get()
	if !present {
		return foundryvalue.Optional[Factor]{}
	}
	return foundryvalue.Set(Factor{
		Key:            item.Key,
		Scope:          item.Scope,
		Identity:       item.Identity,
		Generation:     item.Generation,
		Ciphertext:     item.Ciphertext,
		CreatedAt:      item.CreatedAt,
		PendingUntil:   item.PendingUntil,
		ConfirmedAt:    item.ConfirmedAt,
		LastStep:       item.LastStep,
		RecoveryHashes: item.RecoveryHashes,
	})
}

