// FactorAuditFields reads model-owned history through its declared codecs, without populating a partial model.
// Get on a redacted field reports an explicit error; its Snapshot remains available for deliberate audit export.
func FactorAuditFields(history record.Model[Factor, string]) (FactorAuditFieldSet, error) {
	view, err := record.Inspect(history)
	if err != nil {
		return FactorAuditFieldSet{}, err
	}
	var fields FactorAuditFieldSet
	fields.Key, err = record.ReadField(view, "key", codec.String[string]())
	if err != nil {
		return FactorAuditFieldSet{}, err
	}
	fields.Scope, err = record.ReadField(view, "scope", codec.String[string]())
	if err != nil {
		return FactorAuditFieldSet{}, err
	}
	fields.Identity, err = record.ReadField(view, "identity", codec.JSON[model.Identity]())
	if err != nil {
		return FactorAuditFieldSet{}, err
	}
	fields.Generation, err = record.ReadField(view, "generation", codec.ID[Factor]())
	if err != nil {
		return FactorAuditFieldSet{}, err
	}
	fields.Ciphertext, err = record.ReadField(view, "ciphertext", codec.String[string]())
	if err != nil {
		return FactorAuditFieldSet{}, err
	}
	fields.CreatedAt, err = record.ReadField(view, "created_at", codec.DateTime())
	if err != nil {
		return FactorAuditFieldSet{}, err
	}
	fields.PendingUntil, err = record.ReadField(view, "pending_until", codec.Nullable(codec.DateTime()))
	if err != nil {
		return FactorAuditFieldSet{}, err
	}
	fields.ConfirmedAt, err = record.ReadField(view, "confirmed_at", codec.Nullable(codec.DateTime()))
	if err != nil {
		return FactorAuditFieldSet{}, err
	}
	fields.LastStep, err = record.ReadField(view, "last_step", codec.Nullable(codec.Signed[int64]()))
	if err != nil {
		return FactorAuditFieldSet{}, err
	}
	fields.RecoveryHashes, err = record.ReadField(view, "recovery_hashes", codec.JSON[[]string]())
	if err != nil {
		return FactorAuditFieldSet{}, err
	}
	return fields, nil
}

// FactorAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func FactorAuditing(policy FactorAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Factor]()
		if err != nil {
			return err
		}
		return RegisterFactorObserver(registrar, pool, NewFactorObserver(name), func(resolver foundation.Resolver) (func() FactorHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() FactorHooks {
				write := func(ctx context.Context, tx *database.Tx, changes FactorChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return FactorHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
